//! Typed Tauri commands (TypeScript bindings generated by tauri-specta).
//!
//! Tauri injects `State`, `WebviewWindow` and `AppHandle` by value and calls
//! commands over IPC, so `needless_pass_by_value` and `must_use_candidate`
//! do not apply to this module.
#![allow(clippy::needless_pass_by_value, clippy::must_use_candidate)]

use serde::{Deserialize, Serialize};
use specta::Type;
use tauri::{AppHandle, Runtime, State, WebviewWindow};
use tauri_plugin_opener::OpenerExt;

use crate::chat::{Effort, LlmStatus};
use crate::core::CoreStatus;
use crate::island::IslandState;
use crate::island::geometry::HitRect;
use crate::protocol::{self, Message};
use crate::settings::{SettingValue, SettingsState};
use crate::settings_window;
use crate::started_at;
use crate::state::AppState;

#[derive(Debug, Serialize, Type, thiserror::Error)]
#[error("{message}")]
pub struct CommandError {
    pub message: String,
}

impl From<tauri::Error> for CommandError {
    fn from(e: tauri::Error) -> Self {
        tracing::warn!(error = %e, "command failed");
        Self {
            message: "EV couldn't do that.".into(),
        }
    }
}

/// The UI reports the pill's current interactive area after every shape change.
#[tauri::command]
#[specta::specta]
pub fn island_set_hit_rect(state: State<'_, IslandState>, rect: HitRect) {
    state.set_hit_rect(rect);
}

/// Opening the panel makes the island focusable and focuses it so the input
/// can take typing; closing returns to never-focus and, on Windows, hands
/// keyboard focus back to the app that had it.
///
/// # Errors
/// When the window rejects the focus change.
#[tauri::command]
#[specta::specta]
pub fn island_set_panel_open<R: Runtime>(
    window: WebviewWindow<R>,
    open: bool,
) -> Result<(), CommandError> {
    window.set_focusable(open)?;
    if open {
        window.set_focus()?;
    } else if cfg!(windows) && window.is_focused()? {
        // Windows keeps focus on a window that just became non-activating.
        // Hiding activates the next window in z-order (the app the user came
        // from); showing again does not activate (WS_EX_NOACTIVATE).
        window.hide()?;
        window.show()?;
    }
    Ok(())
}

#[tauri::command]
#[specta::specta]
pub fn core_status(state: State<'_, AppState>) -> CoreStatus {
    state.core_status()
}

#[tauri::command]
#[specta::specta]
pub fn app_quit<R: Runtime>(app: AppHandle<R>) {
    tracing::info!("quit requested from island");
    app.exit(0);
}

/// Spike S1: frame-time statistics for one island morph, written to app.log.
#[derive(Clone, Debug, Deserialize, Type)]
pub struct FrameStats {
    pub label: String,
    pub frames: u32,
    pub dropped: u32,
    pub worst_us: u32,
    pub p95_us: u32,
    /// Input (click / pointer) to first rendered frame of the morph.
    pub first_frame_us: u32,
    /// Morph start until the spring is at rest.
    pub settle_ms: u32,
    /// `devicePixelRatio` × 100 (100, 125, 150 …).
    pub dpr_percent: u32,
}

#[tauri::command]
#[specta::specta]
pub fn spike_report_frames(stats: FrameStats) {
    tracing::info!(
        label = %stats.label,
        frames = stats.frames,
        dropped = stats.dropped,
        worst_us = stats.worst_us,
        p95_us = stats.p95_us,
        first_frame_us = stats.first_frame_us,
        settle_ms = stats.settle_ms,
        dpr_percent = stats.dpr_percent,
        "spike s1 frame stats"
    );
}

/// Spike S2: the island's first painted frame, measured from process start
/// (budget: cold start -> island visible <= 1.5 s). Logged once.
#[tauri::command]
#[specta::specta]
pub fn spike_island_painted(state: State<'_, AppState>) {
    if state.mark_painted() {
        let elapsed_ms = u64::try_from(started_at().elapsed().as_millis()).unwrap_or(u64::MAX);
        tracing::info!(elapsed_ms, "spike s2 island painted");
    }
}

const CORE_DOWN_TEXT: &str = "EV's core isn't running yet. Try again in a moment.";

/// Send a chat message; returns the turn id that every `ChatUpdate` of this
/// turn carries. A new message cancels a reply that is still streaming.
///
/// # Errors
/// When core is not connected or the text exceeds the protocol limit.
#[tauri::command]
#[specta::specta]
pub fn chat_send(
    state: State<'_, AppState>,
    text: String,
    effort: Option<Effort>,
) -> Result<String, CommandError> {
    let message = protocol::chat_send(&text, effort.map(Into::into)).map_err(|_| CommandError {
        message: "That message is too long.".into(),
    })?;
    let Message::ChatSend(send) = &message else {
        return Err(CommandError {
            message: "EV couldn't do that.".into(),
        });
    };
    let turn_id = send.id.to_string();
    state.link.send(message).map_err(|_| CommandError {
        message: CORE_DOWN_TEXT.into(),
    })?;
    Ok(turn_id)
}

/// # Errors
/// When core is not connected or `turn_id` is not a turn id.
#[tauri::command]
#[specta::specta]
pub fn chat_cancel(state: State<'_, AppState>, turn_id: String) -> Result<(), CommandError> {
    let message = protocol::chat_cancel(&turn_id).map_err(|_| CommandError {
        message: "EV couldn't do that.".into(),
    })?;
    state.link.send(message).map_err(|_| CommandError {
        message: CORE_DOWN_TEXT.into(),
    })
}

#[tauri::command]
#[specta::specta]
pub fn llm_status(state: State<'_, AppState>) -> LlmStatus {
    state.llm_status()
}

fn send(
    state: &AppState,
    message: Result<Message, crate::error::AppError>,
) -> Result<(), CommandError> {
    let message = message.map_err(|_| CommandError {
        message: "EV couldn't do that.".into(),
    })?;
    state.link.send(message).map_err(|_| CommandError {
        message: CORE_DOWN_TEXT.into(),
    })
}

/// Ask core for the current settings; the answer arrives as `SettingsChanged`.
///
/// # Errors
/// When core is not connected.
#[tauri::command]
#[specta::specta]
pub fn settings_refresh(state: State<'_, AppState>) -> Result<(), CommandError> {
    send(&state, protocol::config_get())
}

/// Change one setting; core answers with `SettingsChanged` or `SettingRejected`.
///
/// # Errors
/// When core is not connected.
#[tauri::command]
#[specta::specta]
pub fn settings_set(
    state: State<'_, AppState>,
    section: String,
    key: String,
    value: SettingValue,
) -> Result<(), CommandError> {
    send(&state, protocol::config_set(&section, &key, value.into()))
}

/// Return one setting to its default.
///
/// # Errors
/// When core is not connected.
#[tauri::command]
#[specta::specta]
pub fn settings_reset(
    state: State<'_, AppState>,
    section: String,
    key: String,
) -> Result<(), CommandError> {
    send(&state, protocol::config_reset(&section, &key))
}

/// The last settings core reported, if any.
#[tauri::command]
#[specta::specta]
pub fn settings_state(state: State<'_, AppState>) -> Option<SettingsState> {
    state.settings()
}

/// # Errors
/// When the window cannot be created.
#[tauri::command]
#[specta::specta]
pub fn settings_open<R: Runtime>(app: AppHandle<R>) -> Result<(), CommandError> {
    settings_window::open(&app).map_err(CommandError::from)
}

/// Open config.toml in the user's default editor.
///
/// # Errors
/// When no application can open it.
#[tauri::command]
#[specta::specta]
pub fn open_config_file<R: Runtime>(
    app: AppHandle<R>,
    state: State<'_, AppState>,
) -> Result<(), CommandError> {
    let path = state.data_dir.join("config.toml");
    app.opener()
        .open_path(path.to_string_lossy(), None::<&str>)
        .map_err(|e| {
            tracing::warn!(error = %e, "open config file failed");
            CommandError {
                message: "Couldn't open the config file.".into(),
            }
        })
}

/// Open the logs folder.
///
/// # Errors
/// When no application can open it.
#[tauri::command]
#[specta::specta]
pub fn open_logs_folder<R: Runtime>(
    app: AppHandle<R>,
    state: State<'_, AppState>,
) -> Result<(), CommandError> {
    let path = state.data_dir.join("logs");
    app.opener()
        .open_path(path.to_string_lossy(), None::<&str>)
        .map_err(|e| {
            tracing::warn!(error = %e, "open logs folder failed");
            CommandError {
                message: "Couldn't open the logs folder.".into(),
            }
        })
}
